('Germany','2025-02-05 15:46:41.300542','2025-02-05 15:46:41.300542','Administrator','Administrator',0,0,'Germany',0,'{{ address_line1 }}<br>\n{% if address_line2 %}{{ address_line2 }}<br>{% endif -%}\n{% if country in [\"Germany\", \"Deutschland\"] %}\n    {{ pincode }} {{ city }}\n{% else %}\n    {{ pincode }} {{ city | upper }}<br>\n    {{ country | upper }}\n{% endif %}\n',NULL,NULL,NULL,NULL),
('India','2025-02-05 15:46:39.431720','2025-02-05 15:46:39.431720','Administrator','Administrator',0,0,'India',1,'{{ address_line1 }}<br>\n{% if address_line2 %}{{ address_line2 }}<br>{% endif -%}\n{{ city }}<br>\n{% if state %}{{ state }}<br>{% endif -%}\n{% if pincode %}{{ pincode }}<br>{% endif -%}\n{{ country }}<br>\n<br>\n{% if phone %}{{ _(\"Phone\") }}: {{ phone }}<br>{% endif -%}\n{% if fax %}{{ _(\"Fax\") }}: {{ fax }}<br>{% endif -%}\n{% if email_id %}{{ _(\"Email\") }}: {{ email_id }}<br>{% endif -%}\n',NULL,NULL,NULL,NULL),
('Luxembourg','2025-02-05 15:46:41.361137','2025-02-05 15:46:41.361137','Administrator','Administrator',0,0,'Luxembourg',0,'{% if address_line1 %}{{ address_line1 }}<br>{% endif -%}\n{% if address_line2 %}{{ address_line2 }}<br>{% endif -%}\n{% if pincode %}L-{{ pincode }}{% endif -%}{% if city %} {{ city }}{% endif %}<br>\n{% if country %}{{ country | upper }}{% endif %}\n',NULL,NULL,NULL,NULL),
('Taiwan','2025-02-05 15:46:41.282984','2025-02-05 15:46:41.282984','Administrator','Administrator',0,0,'Taiwan',0,'{{ country }}<br>{% if pincode %}{{ pincode }}<br>{% endif -%}{{ county }}{{ city }}{{ address_line1 }}{% if address_line2 %}{{ address_line2 }}{% endif -%}\n{% if phone %}<br>Phone: {{ phone }}{% endif -%}\n{% if fax %}<br>Fax: {{ fax }}{% endif -%}\n{% if email_id %}<br>Email: {{ email_id }}{% endif -%}\n',NULL,NULL,NULL,NULL),
