INSERT INTO `tabClient Script` VALUES
('Employee List Settings','2025-02-06 08:14:46.185631','2025-02-06 08:24:26.322399','Administrator','Administrator',0,0,'Employee','List',NULL,1,'frappe.listview_settings[\'Employee\'] = {\r\n    onload: function(listview) {\r\n        console.log(frappe.session.user);\r\nlistview.page.add_inner_button(\'Filter My Entries\', function() {\r\n                            // Filter based on ownership of the logged-in user\r\n                            listview.filter_area.add([[ \"Employee\", \"owner\", \"=\", frappe.session.user ]]);\r\n                            listview.refresh();\r\n                        });\r\n\r\n                        // Apply the filter on page load\r\n                        listview.filter_area.add([[ \"Employee\", \"owner\", \"=\", frappe.session.user ]]);\r\n                        listview.refresh();\r\n                        if(frappe.session.user == \'onedata@admin.com\'){\r\n            listview.page.wrapper.find(\'.filter-area\').hide();\r\n            \r\n            listview.page.wrapper.find(\'.filter-button\').hide();\r\n\r\n            listview.page.wrapper.find(\'.filter-x-button\').hide();\r\n                        }\r\n    }\r\n};\r\n',NULL,NULL,NULL,NULL),
('Employee Self Edit','2025-02-06 07:42:15.958382','2025-02-06 07:42:15.958382','Administrator','Administrator',0,0,'Employee','Form',NULL,1,'frappe.ui.form.on(\'Employee\', {\r\n    setup: function(frm) {\r\n        frappe.call({\r\n            method: \"frappe.client.get_value\",\r\n            args: {\r\n                doctype: \"User\",\r\n                filters: { \"name\": frappe.session.user },\r\n                fieldname: \"roles\"\r\n            },\r\n            callback: function(response) {\r\n                if (response.message) {\r\n                    let roles = response.message.roles;\r\n                    \r\n                    if (roles.includes(\"onedata\")  && !roles.includes(\"HR Manager\")) {\r\n                        frm.set_query(\"name\", function() {\r\n                            return {\r\n                                filters: { \"owner\": frappe.session.user }\r\n                            };\r\n                        });\r\n                    }\r\n                    \r\n                }\r\n            }\r\n        });\r\n    }\r\n});\r\n',NULL,NULL,NULL,NULL),
('event mail','2025-02-05 20:08:20.346824','2025-02-05 20:23:26.413697','Administrator','Administrator',0,0,'Event','Form',NULL,1,'frappe.ui.form.on(\"Event\", {\r\n    refresh: function (frm) {\r\n        frm.add_custom_button(\"Send Reminder Now\", function () {\r\n            frappe.call({\r\n                method: \"frappe.core.doctype.communication.email.make\",\r\n                args: {\r\n                    recipients: frm.doc.owner,\r\n                    subject: `Reminder: Upcoming Event ${frm.doc.name}`,\r\n                    content: `Your event \'${frm.doc.name}\' is scheduled soon. Don\'t forget to attend!`\r\n                },\r\n                callback: function () {\r\n                    frappe.msgprint(\"Reminder Sent Successfully!\");\r\n                }\r\n            });\r\n        });\r\n         frm.add_custom_button(\"Send Notification\", function () {\r\n            \r\n            frappe.call({\r\n                method: \"erpnext.send_notification.send_notification\",\r\n                args: {\r\n                    event_name: frm.doc.name,\r\n                    recipient: frm.doc.owner\r\n                },\r\n                callback: function () {\r\n                    frappe.msgprint(\"Reminder sent as an in-app notification!\");\r\n                }\r\n            });\r\n        });\r\n    }\r\n});\r\n',NULL,NULL,NULL,NULL),
('Event Test Trigger notification','2025-02-05 19:59:48.998283','2025-02-05 20:08:05.591204','Administrator','Administrator',0,0,'Event','Form',NULL,0,'frappe.ui.form.on(\'Event\', {\r\n    refresh(frm) {\r\n        if (frm.doc.enable_custom_schedule) {\r\n            frm.add_custom_button(__(\'Trigger Reminders\'), function () {\r\n                frappe.call({\r\n                    method: \"your_custom_app.notifications.create_custom_schedule\",\r\n                    args: {\r\n                        event_name: frm.doc.name\r\n                    },\r\n                    callback: function(response) {\r\n                        frappe.msgprint(__(\'Event reminders have been triggered.\'));\r\n                    }\r\n                });\r\n            });\r\n        }\r\n    }\r\n});\r\n',NULL,NULL,NULL,NULL),
('Lead Convert to  Customer','2025-02-05 15:51:18.902305','2025-02-05 15:52:48.366260','Administrator','Administrator',0,0,'Lead','List','CRM',1,'frappe.listview_settings[\'Lead\'] = {\r\n    onload: function (listview) {\r\n        listview.page.add_action_item(__(\'Convert to Customer\'), function () {\r\n            let selected = listview.get_checked_items().map(d => d.name); // Get selected lead names\r\n            if (selected.length === 0) {\r\n                frappe.msgprint(__(\'Please select at least one Lead.\'));\r\n                return;\r\n            }\r\n\r\n            frappe.call({\r\n                method: \"erpnext.onedata.bulk_convert_leads_to_customers\",\r\n                args: { leads: JSON.stringify(selected) },\r\n                callback: function (r) {\r\n                    if (r.message) {\r\n                        let successCount = r.message.success.length;\r\n                        let errorCount = r.message.errors.length;\r\n\r\n                        frappe.msgprint(`${successCount} Leads converted to Customers.`);\r\n                        if (errorCount > 0) {\r\n                            frappe.msgprint(`Errors: ${r.message.errors.join(\", \")}`);\r\n                        }\r\n\r\n                        listview.refresh(); // Refresh the list view\r\n                    }\r\n                }\r\n            });\r\n        });\r\n    }\r\n};\r\n',NULL,NULL,NULL,NULL),
('Lead Number Restrict','2025-02-06 07:57:02.517643','2025-02-06 08:02:22.504189','Administrator','Administrator',0,0,'Lead','Form',NULL,1,'frappe.ui.form.on(\"Lead\", {\r\n    validate: function(frm) {\r\n        let phone = (frm.doc.phone || \"\").trim();\r\n        if (!phone.startsWith(\"+\")) {\r\n            frappe.msgprint({\r\n                title: \"Invalid Phone Number\",\r\n                message: \"Phone number must start with a \'+\' followed by the country code.\",\r\n                indicator: \"red\"\r\n            });\r\n            frappe.validated = false;\r\n            return;\r\n        }\r\n\r\n        let digitsOnly = phone.replace(/\\D/g, \"\"); \r\n        if (digitsOnly.length < 8 || digitsOnly.length > 15) {\r\n            frappe.msgprint({\r\n                title: \"Invalid Phone Number\",\r\n                message: \"Phone number must be between 8 to 15 digits (excluding the \'+\').\",\r\n                indicator: \"red\"\r\n            });\r\n            frappe.validated = false;\r\n        }\r\n    }\r\n});\r\n',NULL,NULL,NULL,NULL),
('Weather Data Fetch','2025-02-06 08:10:04.213134','2025-02-06 08:10:04.213134','Administrator','Administrator',0,0,'Weather Data','List',NULL,1,'frappe.listview_settings[\'Weather Data\'] = {\r\n    onload: function(listview) {\r\n        // Ensure the button is only added once\r\n        if (!listview.fetch_weather_button) {\r\n            listview.fetch_weather_button = listview.page.add_button(\'Fetch Weather\', function() {\r\n                frappe.call({\r\n                    method: \"erpnext.weather_data.fetch_weather\",\r\n                    callback: function(response) {\r\n                        if (response.message) {\r\n                            frappe.msgprint({\r\n                                title: \"Weather Data Updated\",\r\n                                message: \"Weather data has been successfully fetched!\",\r\n                                indicator: \"green\"\r\n                            });\r\n                            listview.refresh();\r\n                        } else {\r\n                            frappe.msgprint({\r\n                                title: \"Error\",\r\n                                message: \"Failed to fetch weather data. Please check logs.\",\r\n                                indicator: \"red\"\r\n                            });\r\n                        }\r\n                    }\r\n                });\r\n            });\r\n\r\n            listview.fetch_weather_button.addClass(\"btn-primary\"); // Highlight the button\r\n        }\r\n    }\r\n};\r\n',NULL,NULL,NULL,NULL);
