('ibo9aejhm0','2025-02-06 08:09:46.491122','2025-02-06 08:09:46.491122','Administrator','Administrator',0,0,'Weather Data Fetch','Client Script',0,NULL,'{\n \"creation\": \"2025-02-06 08:05:33.647084\",\n \"docstatus\": 0,\n \"doctype\": \"Client Script\",\n \"dt\": \"Weather Data\",\n \"enabled\": 1,\n \"idx\": 0,\n \"modified\": \"2025-02-06 08:09:26.935314\",\n \"modified_by\": \"Administrator\",\n \"module\": null,\n \"name\": \"Weather Data Fetch\",\n \"owner\": \"Administrator\",\n \"script\": \"frappe.listview_settings[\'Weather Data\'] = {\\r\\n    onload: function(listview) {\\r\\n        // Ensure the button is only added once\\r\\n        if (!listview.fetch_weather_button) {\\r\\n            listview.fetch_weather_button = listview.page.add_button(\'Fetch Weather\', function() {\\r\\n                frappe.call({\\r\\n                    method: \\\"erpnext.weather_data.fetch_weather\\\",\\r\\n                    callback: function(response) {\\r\\n                        if (response.message) {\\r\\n                            frappe.msgprint({\\r\\n                                title: \\\"Weather Data Updated\\\",\\r\\n                                message: \\\"Weather data has been successfully fetched!\\\",\\r\\n                                indicator: \\\"green\\\"\\r\\n                            });\\r\\n                            listview.refresh();\\r\\n                        } else {\\r\\n                            frappe.msgprint({\\r\\n                                title: \\\"Error\\\",\\r\\n                                message: \\\"Failed to fetch weather data. Please check logs.\\\",\\r\\n                                indicator: \\\"red\\\"\\r\\n                            });\\r\\n                        }\\r\\n                    }\\r\\n                });\\r\\n            });\\r\\n\\r\\n            listview.fetch_weather_button.addClass(\\\"btn-primary\\\"); // Highlight the button\\r\\n        }\\r\\n    }\\r\\n};\\r\\n\",\n \"view\": \"Form\"\n}',NULL,NULL,NULL,NULL),
