('l3gqerqq3u','2025-02-06 08:14:27.239322','2025-02-06 08:14:27.239322','Administrator','Administrator',0,0,'Employee List Settings','Client Script',0,NULL,'{\n \"creation\": \"2025-02-06 07:44:11.379733\",\n \"docstatus\": 0,\n \"doctype\": \"Client Script\",\n \"dt\": \"Employee\",\n \"enabled\": 1,\n \"idx\": 0,\n \"modified\": \"2025-02-06 07:44:11.379733\",\n \"modified_by\": \"Administrator\",\n \"module\": null,\n \"name\": \"Employee List Settings\",\n \"owner\": \"Administrator\",\n \"script\": \"frappe.listview_settings[\'Employee\'] = {\\r\\n    onload: function(listview) {\\r\\n        frappe.call({\\r\\n            method: \\\"frappe.client.get_value\\\",\\r\\n            args: {\\r\\n                doctype: \\\"User\\\",\\r\\n                filters: { \\\"name\\\": frappe.session.user },\\r\\n                fieldname: \\\"roles\\\"\\r\\n            },\\r\\n            callback: function(response) {\\r\\n                if (response.message) {\\r\\n                    let roles = response.message.roles;\\r\\n\\r\\n                    if (roles.includes(\\\"onedata\\\") && !roles.includes(\\\"HR Manager\\\")) {\\r\\n                        listview.page.add_inner_button(\'Filter My Entries\', function() {\\r\\n                            listview.filter_area.add([[ \\\"Employee\\\", \\\"owner\\\", \\\"=\\\", frappe.session.user ]]);\\r\\n                            listview.refresh();\\r\\n                        });\\r\\n\\r\\n                        // Apply filter on page load\\r\\n                        listview.filter_area.add([[ \\\"Employee\\\", \\\"owner\\\", \\\"=\\\", frappe.session.user ]]);\\r\\n                        listview.refresh();\\r\\n                    }\\r\\n                }\\r\\n            }\\r\\n        });\\r\\n    }\\r\\n};\\r\\n\",\n \"view\": \"Form\"\n}',NULL,NULL,NULL,NULL);
