('Point of Sale','2016-05-05 17:16:18.564460','2019-09-05 17:20:30.726659','Administrator','Administrator',0,0,'Sales Invoice','Accounts',NULL,'Yes',1,0,'JS',0,'<style>\n	.print-format table, .print-format tr, \n	.print-format td, .print-format div, .print-format p {\n		font-family: Monospace;\n		line-height: 200%;\n		vertical-align: middle;\n	}\n	@media screen {\n		.print-format {\n			width: 4in;\n			padding: 0.25in;\n			min-height: 8in;\n		}\n	}\n</style>\n\n<p class=\"text-center\">\n	{{ company }}<br>\n	{{  __(\"POS No : \") }} {{ offline_pos_name }}<br>\n</p>\n<p>\n	<b>{{ __(\"Customer\") }}:</b> {{ customer }}<br>\n</p>\n\n<p>\n	<b>{{ __(\"Date\") }}:</b> {{ dateutil.global_date_format(posting_date) }}<br>\n</p>\n\n<hr>\n<table class=\"table table-condensed cart no-border\">\n	<thead>\n		<tr>\n			<th width=\"50%\">{{ __(\"Item\") }}</b></th>\n			<th width=\"25%\" class=\"text-right\">{{ __(\"Qty\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ __(\"Amount\") }}</th>\n		</tr>\n	</thead>\n	<tbody>\n		{% for item in items %}\n		<tr>\n			<td>\n				{{ item.item_name }}\n			</td>\n			<td class=\"text-right\">{{ format_number(item.qty, null,precision(\"difference\")) }}<br>@ {{ format_currency(item.rate, currency) }}</td>\n			<td class=\"text-right\">{{ format_currency(item.amount, currency) }}</td>\n		</tr>\n		{% endfor %}\n	</tbody>\n</table>\n\n<table class=\"table table-condensed no-border\">\n	<tbody>\n		<tr>\n			<td class=\"text-right\" style=\"width: 70%\">\n				{{ __(\"Net Total\") }}\n			</td>\n			<td class=\"text-right\">\n				{{ format_currency(total, currency) }}\n			</td>\n		</tr>\n		{% for row in taxes %}\n		{% if not row.included_in_print_rate %}\n		<tr>\n			<td class=\"text-right\" style=\"width: 70%\">\n				{{ row.description }}\n			</td>\n			<td class=\"text-right\">\n				{{ format_currency(row.tax_amount, currency) }}\n			</td>\n		</tr>\n		{% endif %}\n		{% endfor %}\n		{% if discount_amount %}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				{{ __(\"Discount\") }}\n			</td>\n			<td class=\"text-right\">\n				{{ format_currency(discount_amount, currency) }}\n			</td>\n		</tr>\n		{% endif %}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ __(\"Grand Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ format_currency(grand_total, currency) }}\n			</td>\n		</tr>\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ __(\"Paid Amount\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ format_currency(paid_amount, currency) }}\n			</td>\n		</tr>\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ __(\"Qty Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ qty_total }}\n			</td>\n		</tr>\n	</tbody>\n</table>\n\n\n<hr>\n<p>{{ terms }}</p>\n<p class=\"text-center\">{{ __(\"Thank you, please visit again.\") }}</p>',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,'Default',NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
('POS Invoice','2011-12-21 11:08:55.000000','2021-04-15 15:23:28.867135','Administrator','Administrator',0,1,'POS Invoice','Selling',NULL,'Yes',1,0,'Jinja',0,'<style>\n	.print-format table, .print-format tr, \n	.print-format td, .print-format div, .print-format p {\n		line-height: 150%;\n		vertical-align: middle;\n	}\n	@media screen {\n		.print-format {\n			width: 4in;\n			padding: 0.25in;\n			min-height: 8in;\n		}\n	}\n</style>\n\n{% if letter_head %}\n    {{ letter_head }}\n{% endif %}\n\n<p class=\"text-center\" style=\"margin-bottom: 1rem\">\n	{{ doc.company }}<br>\n	<b>{{ doc.select_print_heading or _(\"Invoice\") }}</b><br>\n</p>\n<p>\n	<b>{{ _(\"Receipt No\") }}:</b> {{ doc.name }}<br>\n	<b>{{ _(\"Cashier\") }}:</b> {{ doc.owner }}<br>\n	<b>{{ _(\"Customer\") }}:</b> {{ doc.customer_name }}<br>\n	<b>{{ _(\"Date\") }}:</b> {{ doc.get_formatted(\"posting_date\") }}<br>\n	<b>{{ _(\"Time\") }}:</b> {{  doc.get_formatted(\"posting_time\") }}<br>\n</p>\n\n<hr>\n<table class=\"table table-condensed\">\n	<thead>\n		<tr>\n			<th width=\"50%\">{{ _(\"Item\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Qty\") }}</th>\n			<th width=\"25%\" class=\"text-right\">{{ _(\"Amount\") }}</th>\n		</tr>\n	</thead>\n	<tbody>\n		{%- for item in doc.items -%}\n		<tr>\n			<td>\n				{{ item.item_code }}\n				{%- if item.item_name != item.item_code -%}\n					<br>{{ item.item_name }}\n				{%- endif -%}\n				{%- if item.serial_no -%}\n					<br><b>{{ _(\"SR.No\") }}:</b><br>\n					{{ item.serial_no | replace(\"\\n\", \", \") }}\n				{%- endif -%}\n			</td>\n			<td class=\"text-right\">{{ item.qty }}<br>@ {{ item.get_formatted(\"rate\") }}</td>\n			<td class=\"text-right\">{{ item.get_formatted(\"amount\") }}</td>\n		</tr>\n		{%- endfor -%}\n	</tbody>\n</table>\n<table class=\"table table-condensed no-border\">\n	<tbody>\n		<tr>\n			{% if doc.flags.show_inclusive_tax_in_print %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total Excl. Tax\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"net_total\", doc) }}\n				</td>\n			{% else %}\n				<td class=\"text-right\" style=\"width: 70%\">\n					{{ _(\"Total\") }}\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"total\", doc) }}\n				</td>\n			{% endif %}\n		</tr>\n		{%- for row in doc.taxes -%}\n		  {%- if not row.included_in_print_rate or doc.flags.show_inclusive_tax_in_print -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 70%\">\n				    {% if \'%\' in row.description %}\n					    {{ row.description }}\n					{% else %}\n					    {{ row.description }}@{{ row.rate }}%\n					{% endif %}\n				</td>\n				<td class=\"text-right\">\n					{{ row.get_formatted(\"tax_amount\", doc) }}\n				</td>\n			<tr>\n		  {%- endif -%}\n		{%- endfor -%}\n\n		{%- if doc.discount_amount -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				{{ _(\"Discount\") }}\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"discount_amount\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Grand Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"grand_total\") }}\n			</td>\n		</tr>\n		{%- if doc.rounded_total -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Rounded Total\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"rounded_total\") }}\n			</td>\n		</tr>\n		{%- endif -%}\n		{%- for row in doc.payments -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 70%\">\n				    {{ row.mode_of_payment }}\n				</td>\n				<td class=\"text-right\">\n					{{ row.get_formatted(\"amount\", doc) }}\n				</td>\n			<tr>\n		{%- endfor -%}\n		<tr>\n			<td class=\"text-right\" style=\"width: 75%\">\n				<b>{{ _(\"Paid Amount\") }}</b>\n			</td>\n			<td class=\"text-right\">\n				{{ doc.get_formatted(\"paid_amount\") }}\n			</td>\n		</tr>\n		{%- if doc.change_amount -%}\n			<tr>\n				<td class=\"text-right\" style=\"width: 75%\">\n					<b>{{ _(\"Change Amount\") }}</b>\n				</td>\n				<td class=\"text-right\">\n					{{ doc.get_formatted(\"change_amount\") }}\n				</td>\n			</tr>\n		{%- endif -%}\n	</tbody>\n</table>\n<hr>\n<p>{{ doc.terms or \"\" }}</p>\n<p class=\"text-center\">{{ _(\"Thank you, please visit again.\") }}</p>',NULL,0.000000000,0.000000000,0.000000000,0.000000000,0,0,0,0,0,NULL,NULL,NULL,NULL,0,0,NULL,NULL,NULL,NULL),
