INSERT INTO `tabServer Script` VALUES
('create_custom_schedule','2025-02-05 19:54:40.605999','2025-02-05 19:54:40.605999','Administrator','Administrator',0,0,'Scheduler Event',NULL,'All',NULL,'Before Insert',NULL,0,NULL,0,'import frappe\r\nfrom datetime import timedelta\r\nfrom frappe.utils import get_datetime\r\nfrom frappe.core.doctype.scheduled_job.scheduled_job import log_error\r\n\r\n@frappe.whitelist()\r\ndef create_custom_schedule(event_name):\r\n    # Fetch the event document\r\n    event = frappe.get_doc(\"Event\", event_name)\r\n    \r\n    # Check if custom schedule is enabled\r\n    if not event.enable_custom_schedule:\r\n        return\r\n\r\n    # Parse the custom schedule interval (e.g., \"1 week, 1 day, 1 hour, 1 minute\")\r\n    intervals = event.custom_schedule_interval.split(\',\')\r\n\r\n    # Calculate the target datetime for each interval and schedule reminder jobs\r\n    for interval in intervals:\r\n        interval = interval.strip()\r\n        target_datetime = calculate_reminder_time(event, interval)\r\n        \r\n        if target_datetime:\r\n            schedule_reminder(target_datetime, event, interval)\r\n\r\ndef calculate_reminder_time(event, interval):\r\n    \"\"\"\r\n    Calculate the reminder time based on the event datetime and the interval (1 week, 1 day, 1 hour, 1 minute).\r\n    \"\"\"\r\n    if \"week\" in interval:\r\n        weeks = int(interval.split()[0])\r\n        target_time = get_datetime(event.event_datetime) - timedelta(weeks=weeks)\r\n    elif \"day\" in interval:\r\n        days = int(interval.split()[0])\r\n        target_time = get_datetime(event.event_datetime) - timedelta(days=days)\r\n    elif \"hour\" in interval:\r\n        hours = int(interval.split()[0])\r\n        target_time = get_datetime(event.event_datetime) - timedelta(hours=hours)\r\n    elif \"minute\" in interval:\r\n        minutes = int(interval.split()[0])\r\n        target_time = get_datetime(event.event_datetime) - timedelta(minutes=minutes)\r\n    else:\r\n        return None\r\n\r\n    return target_time\r\n\r\ndef schedule_reminder(target_datetime, event, interval):\r\n    \"\"\"\r\n    Schedule the reminder job at the target datetime.\r\n    \"\"\"\r\n    try:\r\n        frappe.get_doc({\r\n            \"doctype\": \"Scheduler Event\",\r\n            \"event\": \"Send Event Reminder\",\r\n            \"scheduled_time\": target_datetime,\r\n            \"owner\": event.owner,\r\n            \"description\": f\"Send {interval} reminder for event {event.name}\",\r\n            \"method\": \"your_custom_app.notifications.send_event_reminder\",\r\n            \"args\": {\"event_name\": event.name, \"interval\": interval},\r\n        }).insert()\r\n    except Exception as e:\r\n        log_error(f\"Error scheduling reminder for event {event.name}: {e}\")\r\n\r\n@frappe.whitelist()\r\ndef send_event_reminder(event_name, interval):\r\n    \"\"\"\r\n    Send the actual reminder notification for the event.\r\n    \"\"\"\r\n    # Fetch the event document\r\n    event = frappe.get_doc(\"Event\", event_name)\r\n    \r\n    # Prepare the reminder message\r\n    reminder_message = f\"Reminder: The event \'{event.name}\' is scheduled to occur in {interval}.\"\r\n\r\n    # If the event is public, send notifications to all users\r\n    if event.event_type == \"Public\":\r\n        users = frappe.get_all(\"User\", filters={\"enabled\": 1}, fields=[\"name\"])\r\n        for user in users:\r\n            send_notification(user[\"name\"], reminder_message, event)\r\n    \r\n    else:\r\n        # If the event is private, send the reminder to the owner\r\n        send_notification(event.owner, reminder_message, event)\r\n\r\ndef send_notification(user, reminder_message, event):\r\n    \"\"\"\r\n    Helper function to send a Frappe notification.\r\n    \"\"\"\r\n    try:\r\n        # Create a new notification document\r\n        notification = frappe.get_doc({\r\n            \"doctype\": \"Notification\",\r\n            \"subject\": f\"Event Reminder: {event.name}\",\r\n            \"message\": reminder_message,\r\n            \"user\": user,\r\n            \"reference_doctype\": \"Event\",\r\n            \"reference_name\": event.name\r\n        })\r\n\r\n        # Send the notification\r\n        notification.send()\r\n    except Exception as e:\r\n        frappe.log_error(f\"Error sending notification for event {event.name}: {e}\", title=\"Event Reminder Notification\")\r\n',0,5,86400,NULL,NULL,NULL,NULL);
