('e11vnldl32','2025-02-06 08:02:22.526424','2025-02-06 08:02:22.526424','Administrator','Administrator',0,0,'Client Script','Lead Number Restrict','{\"added\":[],\"changed\":[[\"script\",\"frappe.ui.form.on(\\\"Lead\\\", {\\r\\n    validate: function(frm) {\\r\\n        let phone = (frm.doc.phone_number || \\\"\\\").trim();\\r\\n        if (!phone.startsWith(\\\"+\\\")) {\\r\\n            frappe.msgprint({\\r\\n                title: \\\"Invalid Phone Number\\\",\\r\\n                message: \\\"Phone number must start with a \'+\' followed by the country code.\\\",\\r\\n                indicator: \\\"red\\\"\\r\\n            });\\r\\n            frappe.validated = false;\\r\\n            return;\\r\\n        }\\r\\n\\r\\n        let digitsOnly = phone.replace(/\\\\D/g, \\\"\\\"); \\r\\n        if (digitsOnly.length < 8 || digitsOnly.length > 15) {\\r\\n            frappe.msgprint({\\r\\n                title: \\\"Invalid Phone Number\\\",\\r\\n                message: \\\"Phone number must be between 8 to 15 digits (excluding the \'+\').\\\",\\r\\n                indicator: \\\"red\\\"\\r\\n            });\\r\\n            frappe.validated = false;\\r\\n        }\\r\\n    }\\r\\n});\\r\\n\",\"frappe.ui.form.on(\\\"Lead\\\", {\\r\\n    validate: function(frm) {\\r\\n        let phone = (frm.doc.phone || \\\"\\\").trim();\\r\\n        if (!phone.startsWith(\\\"+\\\")) {\\r\\n            frappe.msgprint({\\r\\n                title: \\\"Invalid Phone Number\\\",\\r\\n                message: \\\"Phone number must start with a \'+\' followed by the country code.\\\",\\r\\n                indicator: \\\"red\\\"\\r\\n            });\\r\\n            frappe.validated = false;\\r\\n            return;\\r\\n        }\\r\\n\\r\\n        let digitsOnly = phone.replace(/\\\\D/g, \\\"\\\"); \\r\\n        if (digitsOnly.length < 8 || digitsOnly.length > 15) {\\r\\n            frappe.msgprint({\\r\\n                title: \\\"Invalid Phone Number\\\",\\r\\n                message: \\\"Phone number must be between 8 to 15 digits (excluding the \'+\').\\\",\\r\\n                indicator: \\\"red\\\"\\r\\n            });\\r\\n            frappe.validated = false;\\r\\n        }\\r\\n    }\\r\\n});\\r\\n\"]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
