('kg0takcrlf','2025-02-05 20:23:26.471025','2025-02-05 20:23:26.471025','Administrator','Administrator',0,0,'Client Script','event mail','{\"added\":[],\"changed\":[[\"script\",\"frappe.ui.form.on(\\\"Event\\\", {\\r\\n    refresh: function (frm) {\\r\\n        frm.add_custom_button(\\\"Send Reminder Now\\\", function () {\\r\\n            frappe.call({\\r\\n                method: \\\"frappe.core.doctype.communication.email.make\\\",\\r\\n                args: {\\r\\n                    recipients: frm.doc.owner,\\r\\n                    subject: `Reminder: Upcoming Event ${frm.doc.name}`,\\r\\n                    content: `Your event \'${frm.doc.name}\' is scheduled soon. Don\'t forget to attend!`\\r\\n                },\\r\\n                callback: function () {\\r\\n                    frappe.msgprint(\\\"Reminder Sent Successfully!\\\");\\r\\n                }\\r\\n            });\\r\\n        });\\r\\n         frm.add_custom_button(\\\"Send Notification\\\", function () {\\r\\n            frappe.call({\\r\\n                method: \\\"frappe.desk.notifications.create_notification\\\",\\r\\n                args: {\\r\\n                    type: \\\"Alert\\\",\\r\\n                    document_type: \\\"Event\\\",\\r\\n                    document_name: frm.doc.name,\\r\\n                    subject: `Reminder: Upcoming Event - ${frm.doc.name}`,\\r\\n                    message: `Your event \'${frm.doc.name}\' is scheduled soon. Don\'t forget to attend!`,\\r\\n                    for_user: frm.doc.owner\\r\\n                },\\r\\n                callback: function () {\\r\\n                    frappe.msgprint(\\\"Reminder Sent as Notification!\\\");\\r\\n                }\\r\\n            });\\r\\n        });\\r\\n    }\\r\\n});\\r\\n\",\"frappe.ui.form.on(\\\"Event\\\", {\\r\\n    refresh: function (frm) {\\r\\n        frm.add_custom_button(\\\"Send Reminder Now\\\", function () {\\r\\n            frappe.call({\\r\\n                method: \\\"frappe.core.doctype.communication.email.make\\\",\\r\\n                args: {\\r\\n                    recipients: frm.doc.owner,\\r\\n                    subject: `Reminder: Upcoming Event ${frm.doc.name}`,\\r\\n                    content: `Your event \'${frm.doc.name}\' is scheduled soon. Don\'t forget to attend!`\\r\\n                },\\r\\n                callback: function () {\\r\\n                    frappe.msgprint(\\\"Reminder Sent Successfully!\\\");\\r\\n                }\\r\\n            });\\r\\n        });\\r\\n         frm.add_custom_button(\\\"Send Notification\\\", function () {\\r\\n            \\r\\n            frappe.call({\\r\\n                method: \\\"erpnext.send_notification.send_notification\\\",\\r\\n                args: {\\r\\n                    event_name: frm.doc.name,\\r\\n                    recipient: frm.doc.owner\\r\\n                },\\r\\n                callback: function () {\\r\\n                    frappe.msgprint(\\\"Reminder sent as an in-app notification!\\\");\\r\\n                }\\r\\n            });\\r\\n        });\\r\\n    }\\r\\n});\\r\\n\"]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
