('lnh0m71sq4','2025-02-06 08:15:31.309480','2025-02-06 08:15:31.309480','Administrator','Administrator',0,0,'Client Script','Employee List Settings','{\"added\":[],\"changed\":[[\"script\",\"frappe.listview_settings[\'Employee\'] = {\\r\\n    onload: function(listview) {\\r\\n        frappe.call({\\r\\n            method: \\\"frappe.client.get_value\\\",\\r\\n            args: {\\r\\n                doctype: \\\"User\\\",\\r\\n                filters: { \\\"name\\\": frappe.session.user },\\r\\n                fieldname: \\\"roles\\\"\\r\\n            },\\r\\n            callback: function(response) {\\r\\n                if (response.message) {\\r\\n                    let roles = response.message.roles;\\r\\n\\r\\n                    if (roles.includes(\\\"onedata\\\") && !roles.includes(\\\"HR Manager\\\")) {\\r\\n                        listview.page.add_inner_button(\'Filter My Entries\', function() {\\r\\n                            listview.filter_area.add([[ \\\"Employee\\\", \\\"owner\\\", \\\"=\\\", frappe.session.user ]]);\\r\\n                            listview.refresh();\\r\\n                        });\\r\\n\\r\\n                        // Apply filter on page load\\r\\n                        listview.filter_area.add([[ \\\"Employee\\\", \\\"owner\\\", \\\"=\\\", frappe.session.user ]]);\\r\\n                        listview.refresh();\\r\\n                    }\\r\\n                }\\r\\n            }\\r\\n        });\\r\\n    }\\r\\n};\\r\\n\",\"frappe.listview_settings[\'Employee\'] = {\\r\\n    onload: function(listview) {\\r\\n        alert(frappe.session.user)\\r\\n        frappe.call({\\r\\n            method: \\\"frappe.client.get_value\\\",\\r\\n            args: {\\r\\n                doctype: \\\"User\\\",\\r\\n                filters: { \\\"name\\\": frappe.session.user },\\r\\n                fieldname: \\\"roles\\\"\\r\\n            },\\r\\n            callback: function(response) {\\r\\n                if (response.message) {\\r\\n                    let roles = response.message.roles;\\r\\n\\r\\n                    if (roles.includes(\\\"onedata\\\") && !roles.includes(\\\"HR Manager\\\")) {\\r\\n                        listview.page.add_inner_button(\'Filter My Entries\', function() {\\r\\n                            listview.filter_area.add([[ \\\"Employee\\\", \\\"owner\\\", \\\"=\\\", frappe.session.user ]]);\\r\\n                            listview.refresh();\\r\\n                        });\\r\\n\\r\\n                        // Apply filter on page load\\r\\n                        listview.filter_area.add([[ \\\"Employee\\\", \\\"owner\\\", \\\"=\\\", frappe.session.user ]]);\\r\\n                        listview.refresh();\\r\\n                    }\\r\\n                }\\r\\n            }\\r\\n        });\\r\\n    }\\r\\n};\\r\\n\"]],\"data_import\":null,\"removed\":[],\"row_changed\":[],\"updater_reference\":null}',NULL,NULL,NULL,NULL),
('ltj5in0ncd','2025-02-05 15:52:48.392034','2025-02-05 15:52:48.392034','Administrator','Administrator',0,0,'Client Script','Lead Convert to  Customer','{\"added\":[],\"changed\":[[\"script\",\"frappe.listview_settings[\'Lead\'] = {\\r\\n    onload: function (listview) {\\r\\n        listview.page.add_action_item(__(\'Convert to Customer\'), function () {\\r\\n            let selected = listview.get_checked_items().map(d => d.name); // Get selected lead names\\r\\n            if (selected.length === 0) {\\r\\n                frappe.msgprint(__(\'Please select at least one Lead.\'));\\r\\n                return;\\r\\n            }\\r\\n\\r\\n            frappe.call({\\r\\n                method: \\\"erpnext.opendata.bulk_convert_leads_to_customers\\\",\\r\\n                args: { leads: JSON.stringify(selected) },\\r\\n                callback: function (r) {\\r\\n                    if (r.message) {\\r\\n                        let successCount = r.message.success.length;\\r\\n                        let errorCount = r.message.errors.length;\\r\\n\\r\\n                        frappe.msgprint(`${successCount} Leads converted to Customers.`);\\r\\n                        if (errorCount > 0) {\\r\\n                            frappe.msgprint(`Errors: ${r.message.errors.join(\\\", \\\")}`);\\r\\n                        }\\r\\n\\r\\n                        listview.refresh(); // Refresh the list view\\r\\n                    }\\r\\n                }\\r\\n            });\\r\\n        });\\r\\n    }\\r\\n};\\r\\n\",\"frappe.listview_settings[\'Lead\'] = {\\r\\n    onload: function (listview) {\\r\\n        listview.page.add_action_item(__(\'Convert to Customer\'), function () {\\r\\n            let selected = listview.get_checked_items().map(d => d.name); // Get selected lead names\\r\\n            if (selected.length === 0) {\\r\\n                frappe.msgprint(__(\'Please select at least one Lead.\'));\\r\\n                return;\\r\\n            }\\r\\n\\r\\n        